create table if not exists spiritual.qibla_calculations ( id bigint generated always as identity primary key, from_lat numeric(9,6) not null, from_lng numeric(9,6) not null, kaaba_lat numeric(9,6) not null default 21.4225, kaaba_lng numeric(9,6) not null default 39.8262, bearing numeric(8,4) not null, distance_km numeric(10,2) not null, calculated_by uuid not null references identity.profiles (id) default auth.uid(), tenant_id uuid references core.tenants (id), created_at timestamptz default now(), unique (from_lat, from_lng) );
